<?php
if(getenv('APP_ENV')!=='testing'||getenv('DB_DATABASE')!==':memory:')exit(2);
require '/app/vendor/autoload.php';
$source=str_replace([' implements MustVerifyEmail','    use TwoFactorAuthenticatable;'],['',''],file_get_contents('/app/app/Models/User.php'));file_put_contents('/tmp/AuthBaselineUser.php',$source);require '/tmp/AuthBaselineUser.php';
$source=str_replace('use Illuminate\\Contracts\\Auth\\MustVerifyEmail;','',file_get_contents('/app/app/Actions/Fortify/UpdateUserProfileInformation.php'));file_put_contents('/tmp/AuthBaselineProfile.php',$source);require '/tmp/AuthBaselineProfile.php';
$app=require '/app/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();Illuminate\Support\Facades\Mail::fake();Illuminate\Support\Facades\Notification::fake();Illuminate\Support\Facades\Http::fake();Illuminate\Support\Facades\Storage::fake('public');Illuminate\Support\Facades\Artisan::call('migrate',['--force'=>true]);
$checks=[];$check=function($name,$ok)use(&$checks){$checks[]=['check'=>$name,'passed'=>(bool)$ok];};
$pw='Synthetic-only-Password123!';$u=(new App\Actions\Fortify\CreateNewUser())->create(['name'=>'SyntheticAuth','email'=>'auth@example.test','password'=>$pw,'password_confirmation'=>$pw]);
$check('registration creates hashed password',Illuminate\Support\Facades\Hash::check($pw,$u->password));$check('live model does not require email verification',!($u instanceof Illuminate\Contracts\Auth\MustVerifyEmail));$check('live model lacks two-factor trait',!in_array(Laravel\Fortify\TwoFactorAuthenticatable::class,class_uses_recursive($u)));
try{(new App\Actions\Fortify\CreateNewUser())->create(['name'=>'Duplicate','email'=>'auth@example.test','password'=>$pw,'password_confirmation'=>$pw]);$check('duplicate email rejected',false);}catch(Illuminate\Validation\ValidationException $e){$check('duplicate email rejected',isset($e->errors()['email']));}
(new App\Actions\Fortify\UpdateUserProfileInformation())->update($u,['name'=>'SyntheticRenamed','email'=>'renamed@example.test']);$check('profile name and email persisted',$u->fresh()->email==='renamed@example.test'&&$u->fresh()->name==='SyntheticRenamed');Illuminate\Support\Facades\Notification::assertNothingSent();$check('profile update sends no verification notification',true);
try{(new App\Actions\Fortify\UpdateUserPassword())->update($u,['current_password'=>'wrong','password'=>'New-Synthetic-Password123!','password_confirmation'=>'New-Synthetic-Password123!']);$check('wrong current password rejected',false);}catch(Illuminate\Validation\ValidationException $e){$check('wrong current password rejected',isset($e->errors()['current_password']));}
(new App\Actions\Fortify\UpdateUserPassword())->update($u,['current_password'=>$pw,'password'=>'New-Synthetic-Password123!','password_confirmation'=>'New-Synthetic-Password123!']);$check('password update persists hash',Illuminate\Support\Facades\Hash::check('New-Synthetic-Password123!',$u->fresh()->password));
(new App\Actions\Fortify\ResetUserPassword())->reset($u,['password'=>$pw,'password_confirmation'=>$pw]);$check('password reset action persists hash',Illuminate\Support\Facades\Hash::check($pw,$u->fresh()->password));
$s=new App\Models\Suspension();$s->user_id=$u->id;$s->expiration=now()->subDay();$s->save();Illuminate\Support\Facades\Artisan::call('suspensions:expire');$check('expired suspension removed',!App\Models\Suspension::whereKey($s->id)->exists());
(new App\Actions\Jetstream\DeleteUser())->delete($u);$check('synthetic account deletion persists',!App\Models\User::whereKey($u->id)->exists());$check('foreign keys remain valid',count(Illuminate\Support\Facades\DB::select('PRAGMA foreign_key_check'))===0);
echo json_encode(['scope'=>'action-level auth and scheduler checks with observed-live overlay, not browser reset email delivery','checks'=>$checks],JSON_PRETTY_PRINT),"\n";exit(count(array_filter($checks,fn($c)=>!$c['passed']))?1:0);
